        'import hashlib, hmac, json, time\n\ndef consent_active(button_pressed, spoken_phrase_match, hardware_switch):\n    """All three must be true; there is no software override."""\n    return bool(button_pressed and spoken_phrase_match and hardware_switch)\n\ndef record_segment(stream, key, out_dir, max_seconds=3600):\n    frames, started = [], time.time()\n    while consent_active(*stream.consent_state()) and time.time() - started < max_seconds:\n        frames.append(stream.read(1024))\n    audio = b"".join(frames)\n    digest = hmac.new(key, audio, hashlib.sha256).hexdigest()\n    path = f"{out_dir}/{int(started)}.enc"\n    with open(path, "wb") as fh:\n        fh.write(audio)  # encrypt with the community-held key before this write in production\n    meta = {"started": started, "seconds": len(audio) / 32000,\n            "hmac_sha256": digest, "consent": "explicit"}\n    with open(path + ".json", "w") as fh:\n        json.dump(meta, fh)\n    return path, meta\n',
